import pandas as pd
import numpy as np
import unicodedata

month_map={'Jan':1,'Feb':2,'Mar':3,'Apr':4,'May':5,'Jun':6,'Jul':7,'Aug':8,'Sep':9,'Oct':10,'Nov':11,'Dec':12}

def parse_month_year(s):
    if pd.isna(s):
        return pd.NaT
    s=str(s)
    if s.startswith('Unknown'):
        return pd.NaT
    try:
        mon,year=s.split('-')
        return pd.Timestamp(int(year), month_map[mon], 1)
    except Exception:
        return pd.NaT

def norm_country(x):
    if pd.isna(x) or str(x).strip()=='' :
        return 'Unknown'
    s=unicodedata.normalize('NFKC', str(x).strip())
    low=s.lower()
    if low in {'usa','u.s.a','u.s.a.','us','u.s.','united states','united states of america','united states america'}:
        return 'USA'
    if low in {'uk','u.k.','united kingdom','england','scotland','wales','northern ireland'}:
        return 'UK'
    if low in {'pr china','p.r. china','people\'s republic of china','peoples republic of china'}:
        return 'China'
    if low in {'republic of korea','korea, south','south korea'}:
        return 'South Korea'
    if low in {'iran','iran, islamic republic of'}:
        return 'Iran'
    return s


df=pd.read_csv('benchmark/data.csv')
df['month_dt']=df['month_year'].map(parse_month_year)
df['country_norm']=df['country'].map(norm_country)
df['major_topic']=df['major_topic'].fillna('Unindexed/Unknown')

# Top countries by year (top 8 overall)
top_countries=df['country_norm'].value_counts().head(8).index
geo=df[df['country_norm'].isin(top_countries)].groupby(['month_dt','country_norm']).size().rename('count').reset_index().dropna(subset=['month_dt'])
# convert to wide for chart
gw=geo.pivot_table(index='month_dt', columns='country_norm', values='count', fill_value=0).sort_index()
print('months', len(gw.index), 'cols', len(gw.columns))
print(gw.tail(5))

# topic mix by year top topics excluding unindexed
known=df[df['major_topic']!='Unindexed/Unknown']
top_topics=known['major_topic'].value_counts().head(10).index
tmix=df[df['major_topic'].isin(top_topics)].groupby(['pub_year','major_topic']).size().rename('count').reset_index()
print(tmix.head())
